function lessonIndexes(words){if(!words.length)return items.map((_,i)=>i);const needles=words.map(x=>x.toLowerCase());return items.map((x,i)=>needles.some(n=>x.word.toLowerCase().includes(n)||n.includes(x.word.toLowerCase()))?i:-1).filter(i=>i>=0)}
function imageMarkup(item){if(item.sprite)return `<span class="paper-sprite" style="--col:${item.col};--row:${item.row}"><img src="${esc(item.sprite)}" alt=""></span>`;return `<img src="${esc(item.image)}" alt="">`}
