function lessonTypes(lesson,index){if(LESSON_EXERCISES[themeKey]?.[index])return LESSON_EXERCISES[themeKey][index];const text=(lesson[1]+' '+lesson[2].join(' ')).toLowerCase(),out=[['circle','Prenten aankruisen'],['match','Woord en prent verbinden'],['check','Juist of fout']];if(grade>1)out.push(['words','Invullen met een woordbank']);if(themeKey==='l1t2'&&/(ei|kuiken|geboorte|jong)/.test(text))out.unshift(['birth','Eierleggend of levendbarend']);if((themeKey==='l1t2'&&/(boom|super)/.test(text))||(themeKey==='l2t2'&&/(paddenstoel|lagen|delen)/.test(text)))out.unshift(['parts','Delen bij de prent verbinden']);return out}
function builder(){tool.innerHTML=`<section class="homework-builder"><h2>Huistaak samenstellen</h2><div class="homework-grid"><label class="homework-field">Titel bovenaan<select id="hwTitleKind"><option>Huistaak</option><option>Ik oefen</option><option>Ik herhaal</option></select></label><label class="homework-field">Nummer<input id="hwNumber" type="number" min="1" max="30" value="1"></label><label class="homework-field"><span><input id="hwShowNumber" type="checkbox" checked> Nummer in de titel tonen</span></label></div><h3>Kies per les de oefeningen</h3><p class="homework-hint">Alles start leeg. Vink losse oefeningen aan of kies in één klik de hele les.</p><div class="homework-lesson-plans">${lessons.map((l,i)=>`<fieldset><legend><b>Les ${l[0]}</b> — ${esc(l[1])}</legend><label class="lesson-select-all"><input type="checkbox" data-lesson-all="${i}"> <b>Hele les selecteren</b></label><div>${lessonTypes(l,i).map(t=>`<label><input class="lesson-exercise" type="checkbox" data-lesson="${i}" value="${t[0]}"> ${esc(t[1])}</label>`).join('')}</div></fieldset>`).join('')}</div><label class="homework-field solution-choice"><span><input id="hwSolutions" type="checkbox"> Apart oplossingenblad toevoegen</span></label><div class="homework-actions"><button id="hwPreview">Voorbeeld vernieuwen</button><button class="primary" id="hwPrint">🖨️ Maak PDF / print</button></div></section><div id="homeworkPreview"></div>`;document.querySelectorAll('[data-lesson-all]').forEach(all=>all.onchange=()=>{document.querySelectorAll(`.lesson-exercise[data-lesson="${all.dataset.lessonAll}"]`).forEach(x=>x.checked=all.checked);all.indeterminate=false;generate()});document.querySelectorAll('.lesson-exercise').forEach(x=>x.onchange=()=>{const group=[...document.querySelectorAll(`.lesson-exercise[data-lesson="${x.dataset.lesson}"]`)],all=document.querySelector(`[data-lesson-all="${x.dataset.lesson}"]`),count=group.filter(y=>y.checked).length;all.checked=count===group.length;all.indeterminate=count>0&&count<group.length;generate()});document.querySelector('#hwTitleKind').onchange=generate;document.querySelector('#hwNumber').oninput=generate;document.querySelector('#hwShowNumber').onchange=e=>{document.querySelector('#hwNumber').disabled=!e.target.checked;generate()};document.querySelector('#hwPreview').onclick=generate;document.querySelector('#hwPrint').onclick=async()=>{if(!generate())return;const printButton=document.querySelector('#hwPrint'),oldText=printButton.textContent;printButton.disabled=true;printButton.textContent='Afbeeldingen laden…';document.body.dataset.print='homework';const ready=await waitForPaperImages();if(!ready){delete document.body.dataset.print;printButton.disabled=false;printButton.textContent=oldText;alert('De PDF is nog niet geopend omdat minstens één afbeelding niet kon laden. Vernieuw de pagina en probeer opnieuw.');return}printButton.textContent='PDF openen…';setTimeout(()=>{window.print();printButton.disabled=false;printButton.textContent=oldText},120)};generate()}
async function waitForPaperImages(){const images=[...paper.querySelectorAll('img')];async function load(img,retry=false){if(img.complete&&img.naturalWidth>0){if(img.decode)await img.decode().catch(()=>{});return img.naturalWidth>0}const loaded=await new Promise(resolve=>{const timer=setTimeout(()=>resolve(false),12000);img.onload=()=>{clearTimeout(timer);resolve(true)};img.onerror=()=>{clearTimeout(timer);resolve(false)}});if(loaded&&img.naturalWidth>0){if(img.decode)await img.decode().catch(()=>{});return true}if(!retry){const original=img.currentSrc||img.src,separator=original.includes('?')?'&':'?';img.src=`${original}${separator}printRetry=${Date.now()}`;return load(img,true)}return false}const results=await Promise.all(images.map(img=>load(img)));await new Promise(requestAnimationFrame);await new Promise(requestAnimationFrame);return results.every(Boolean)}
function rotate(list,n){const out=list.slice(0,4);for(let i=0;i<n%out.length;i++)out.push(out.shift());return out}
const exerciseHeading=(n,text)=>`<h3><span class="exercise-number">${n}</span><span class="exercise-instruction">${text}</span></h3>`;
const taskList=items=>`<span class="paper-task-list">${items.map(item=>`<span><i class="task-checkbox"></i><span class="task-text">${item}</span></span>`).join('')}</span>`;
function pictureExercise(sample,n,solutions=false){const answer=sample[0],options=rotate(sample,n);return `<section class="paper-exercise paper-keep">${exerciseHeading(n,`Kruis het vakje aan onder de prent die past bij <b>${esc(displayWord(answer.word))}</b>.`)}<div class="paper-exercise-body"><div class="paper-pictures">${options.map(item=>`<div class="paper-picture ${solutions&&item===answer?'solution-box':''}">${imageMarkup(item)}<span class="paper-checkbox">${solutions&&item===answer?'×':''}</span></div>`).join('')}</div></div></section>`}
function matchExercise(sample,n,solutions=false){const chosen=sample.slice(0,4),right=rotate(chosen,n+1);return `<section class="paper-exercise paper-keep">${exerciseHeading(n,'Verbind elk woord met de juiste prent.')}<div class="paper-exercise-body"><div class="paper-match"><div class="paper-match-column">${chosen.map(item=>`<div class="paper-match-word"><span>${esc(displayWord(item.word))}</span><span class="connect-dot"></span></div>`).join('')}</div><div class="paper-match-column">${right.map(item=>`<div class="paper-match-image"><span class="connect-dot"></span>${imageMarkup(item)}${solutions?`<small>${esc(displayWord(item.word))}</small>`:''}</div>`).join('')}</div></div></div></section>`}
function checkExercise(sample,n,solutions=false){const chosen=sample.slice(0,3);return `<section class="paper-exercise paper-splittable">${exerciseHeading(n,'Omcirkel <b>juist</b> of <b>fout</b>.')}<div class="paper-exercise-body"><div class="paper-checks">${chosen.map((item,i)=>{const trueOne=i%2===0,other=sample[(i+1)%sample.length],text=trueOne?item.definition:other.definition;return `<div class="paper-subquestion"><span><b>${esc(item.word)}</b>: ${esc(text)}</span><span class="${solutions&&trueOne?'solution':''}">juist</span><span class="${solutions&&!trueOne?'solution':''}">fout</span></div>`}).join('')}</div></div></section>`}
function wordExercise(sample,n,solutions=false){const chosen=sample.slice(0,4);return `<section class="paper-exercise paper-keep">${exerciseHeading(n,'Vul het juiste woord in. Kies uit de woordbank.')}<div class="paper-exercise-body"><div class="paper-wordbank">${rotate(chosen,n+2).map(item=>esc(displayWord(item.word))).join(' · ')}</div><div class="paper-lines">${chosen.map(item=>`<div class="paper-subquestion"><p>${esc(item.definition)}</p><p>Dit woord is: <span class="${solutions?'solution':''}">${solutions?esc(displayWord(item.word)):'____________________'}</span></p></div>`).join('')}</div></div></section>`}
function addressExercise(sample,n,solutions=false){return `<section class="paper-exercise paper-keep paper-special">${exerciseHeading(n,'Bekijk de envelop. Omcirkel het volledige adres en kleur de postcode blauw.')}<div class="paper-exercise-body"><img class="paper-address" src="assets/woordenschat-l1/adres-school-l1.svg" alt="Envelop met adres">${solutions?'<p class="solution-note">Oplossing: omcirkel naam, straat, huisnummer, postcode en gemeente. Kleur <b>2880</b> blauw.</p>':''}</div></section>`}
function birthExercise(sample,n,solutions=false){const animals=[['een vogel','woord-vogel.png','ei'],['een vis','woord-vis.png','ei'],['een zoogdier','woord-zoogdier.png','buik'],['een jong dat melk drinkt','woord-zogen.png','buik']];return `<section class="paper-exercise paper-keep paper-special"><h3>${n}. Omcirkel in <b class="egg-key">geel</b> wat uit een ei komt en in <b class="live-key">rood</b> wat uit de buik van de moeder komt.</h3><div class="paper-birth-legend"><span>🥚 uit een ei</span><span>🤰 uit de buik</span></div><div class="paper-birth">${animals.map(a=>`<div class="${solutions?(a[2]==='ei'?'answer-egg':'answer-live'):''}"><img src="assets/${a[1]}" alt="${a[0]}"><span>${esc(a[0])}</span></div>`).join('')}</div></section>`}
function partsExercise(sample,n,solutions=false){const isMushroom=themeKey==='l2t2',src=isMushroom?'assets/images/paddenstoel-delen-realistisch.png':'assets/boom-delen-realistisch.png',labels=isMushroom?['de hoed','de plaatjes','de ring','de steel','de zwamvlok']:['de kruin','het blad','de tak','de stam','de wortels'];return `<section class="paper-exercise paper-keep paper-special"><h3>${n}. Verbind elk woord met het juiste deel van de prent.</h3><div class="paper-parts"><div>${labels.map(x=>`<p>${esc(x)} <span class="connect-dot"></span></p>`).join('')}</div><img src="${src}" alt="Delen"><div class="part-targets">${labels.map((x,i)=>`<i class="connect-dot" title="${esc(x)}"></i>`).join('')}</div></div>${solutions?'<p class="solution-note">Gebruik de voorbeeldprent uit de les om samen te verbeteren.</p>':''}</section>`}
