if(type==='addressParts')return customKeep(n,'Verbind elk woord met het juiste deel van het adres.',`<div class="paper-address-connect"><div class="paper-address-targets"><p><b>Lindestraat</b><span class="connect-dot"></span></p><p><b>123 A</b><span class="connect-dot"></span></p><p><b>2880</b><span class="connect-dot"></span></p><p><b>Bornem</b><span class="connect-dot"></span></p></div><div class="paper-connect-space"></div><div class="paper-address-labels">${['postcode','straatnaam','gemeente','huisnummer'].map(x=>`<p><span class="connect-dot"></span><b>${x}</b></p>`).join('')}</div></div>`);
if(type==='homeStories')return customKeep(n,'Lees of luister. Verbind elk kind met de juiste woning.',`<div class="paper-home-stories"><div class="paper-story-people"><img src="${A+'les9-kind-meisje-v2.png'}" alt="Een meisje"><img src="${A+'les9-kind-rolstoel-v2.png'}" alt="Een jongen in een rolstoel"><img src="${A+'les9-kind-jongen-v2.png'}" alt="Een jongen"></div><div class="paper-story-texts"><p>Ik woon in een huis in de stad. Winkels zijn dichtbij.<span class="connect-dot"></span></p><p>Ik woon in een flat in de stad. Ik speel graag in het park.<span class="connect-dot"></span></p><p>Ik woon in een dorp. Ik heb een tuin en hoor vogels.<span class="connect-dot"></span></p></div><div class="paper-story-space"></div><div class="paper-story-targets"><span class="connect-dot"></span><span class="connect-dot"></span><span class="connect-dot"></span></div><div class="paper-story-houses"><img src="${A+'les9-woning-flat-v2.png'}" alt="Een flat"><img src="${A+'les9-woning-vrijstaand-v2.png'}" alt="Een vrijstaand huis"><img src="${A+'les9-woning-rijhuis-v2.png'}" alt="Een rijhuis"></div></div>`);
if(type==='homeTypes')return customKeep(n,'Verbind elke prent met het juiste woord.',`<div class="paper-home-connect"><div class="paper-home-pictures">${[['vrijstaande-woning.webp','de vrijstaande woning'],['rijhuis.webp','het rijhuis'],['flat.webp','de flat']].map(x=>`<div class="${solutions?'solution-home-'+x[1].replaceAll(' ','-'):''}"><img src="${A+x[0]}" alt="${x[1]}"><span class="connect-dot"></span></div>`).join('')}</div><div class="paper-connect-space"></div><div class="paper-home-labels">${['de flat','de vrijstaande woning','het rijhuis'].map(x=>`<p><span class="connect-dot"></span><b>${x}</b></p>`).join('')}</div></div>`);
if(type==='addressL2')return customKeep(n,'Schrijf je eigen adres uit het hoofd op de brief: straatnaam en huisnummer, postcode en gemeente.',`<img class="paper-wide-image" src="${I+'envelop-adres-school-leeg.svg'}" alt="Lege brief met drie schrijflijnen">${solutions?'<p class="solution-note">Eigen antwoord. Controleer of straatnaam, huisnummer, postcode en gemeente ingevuld zijn.</p>':''}`);
if(type==='addressPartsL2')return customKeep(n,taskList(['Kleur de straatnaam <em class="color-blue">blauw</em>.','Kleur het huisnummer <em class="color-red">rood</em>.','Kleur de postcode <em class="color-green">groen</em>.','Kleur de gemeente <em class="color-yellow">geel</em>.']),`<div class="paper-school-envelope paper-school-envelope-color"><b>GO! Basisschool De Linde</b><p><span>Lindestraat</span><span>123 a</span></p><p><span>2880</span><span>Bornem</span></p></div>`);
if(type==='addressWordsL2')return customKeep(n,'Vul het juiste woord in. Kies uit de woordbank.',`<div class="paper-wordbank">adres · gemeente · deelgemeente · buurgemeente</div><div class="paper-lines paper-address-words"><div class="paper-subquestion"><p>Een dorp of stad met een eigen bestuur is een ____________________.</p></div><div class="paper-subquestion"><p>Een kleiner deel dat bij een gemeente hoort, is een ____________________.</p></div><div class="paper-subquestion"><p>Een gemeente die naast jouw gemeente ligt, is een ____________________.</p></div><div class="paper-subquestion final-address-question"><p>Straatnaam, huisnummer, postcode en gemeente vormen samen je</p><span class="lower-writing-line"></span></div></div>`);
if(type==='bornemMap'||type==='neighbourMap')return customKeep(n,type==='bornemMap'?'Kleur de vier deelgemeenten: Bornem rood, Hingene geel, Mariekerke blauw en Weert groen.':'Omcirkel de buurgemeenten van Bornem.',`<img class="paper-map-image" src="${I+(solutions?(type==='bornemMap'?'kaart-bornem-plaatsen-echt.png':'kaart-bornem-buurgemeenten-echt.png'):'kaart-bornem.png')}" alt="${solutions?'Oplossingskaart':'Onbeantwoorde kaart'} van Bornem">`);
