function exerciseFunction(type){if(type==='circle')return pictureExercise;if(type==='match')return matchExercise;if(type==='words')return wordExercise;if(type==='address')return addressExercise;if(type==='birth')return birthExercise;if(type==='parts')return partsExercise;if(type==='check')return checkExercise;return (sample,n,solutions)=>customExercise(type,n,solutions)}
function page(inner,number,titleKind,lessonTitle,solution=false){const mainTitle=`${titleKind}${number?` ${number}`:''}`;return `<article class="homework-page ${solution?'solutions-page':''}"><header class="homework-header">${solution?'<div class="solutions-label">OPLOSSINGENBLAD</div>':''}<div class="homework-meta"><span>Naam: ____________________</span><span>Datum: ____________</span></div><div class="homework-title"><h1>${esc(mainTitle)}</h1><h2>${esc(lessonTitle)}</h2><p>${esc(themeTitle)}</p></div></header>${inner}</article>`}
function generate(){const number=Math.max(1,+document.querySelector('#hwNumber')?.value||1),showNumber=document.querySelector('#hwShowNumber')?.checked!==false,titleKind=document.querySelector('#hwTitleKind')?.value||'Huistaak',plan=[...document.querySelectorAll('.lesson-exercise:checked')].map(x=>({lesson:+x.dataset.lesson,type:x.value}));if(!plan.length){document.querySelector('#homeworkPreview').innerHTML='<p class="homework-empty">Vink bij minstens één les een oefening aan.</p>';paper.innerHTML='';return false}let normal='',answers='';plan.forEach((choice,i)=>{const indexes=lessonIndexes(lessons[choice.lesson][2]),lessonItems=indexes.map(x=>items[x]),selected=lessonItems.length>=2?lessonItems:items,sample=shuffle(selected).slice(0,Math.min(8,selected.length)),type=choice.type,fn=exerciseFunction(type);normal+=fn(sample,i+1,false);answers+=fn(sample,i+1,true)});const used=[...new Set(plan.map(x=>x.lesson))],numbers=used.map(i=>lessons[i][0]),lessonTitle=used.length===1?`Les ${numbers[0]} – ${lessons[used[0]][1]}`:`Les ${numbers.slice(0,-1).join(', ')} en ${numbers.at(-1)}`,shownNumber=showNumber?number:'';paper.innerHTML=page(normal,shownNumber,titleKind,lessonTitle)+(document.querySelector('#hwSolutions').checked?page(answers,shownNumber,titleKind,lessonTitle,true):'');document.querySelector('#homeworkPreview').innerHTML=`<p class="homework-ready">De huistaak staat klaar: <b>${esc(titleKind)}${shownNumber?` ${shownNumber}`:''} – ${esc(lessonTitle)}</b>. Er staan ${plan.length} gekozen oefeningen in.${document.querySelector('#hwSolutions').checked?' Er wordt ook een oplossingenblad toegevoegd.':''}</p>`;return true}
const originalGenerate=generate;generate=function(){const result=originalGenerate();if(result)applyArticles(paper);return result};
